def compute(vars):
    actual = vars["v1"]
    target = vars["v2"]
    difference = actual - target
    return {
        "value": difference,
        "trace": {
            "actual": actual,
            "target": target,
            "difference": difference,
            "output_meta": {
                "currency": "GBP",
                "scale": "million",
                "unit": None
            }
        }
    }
